package com.rohit.inventory.event; import java.time.Instant; import java.util.UUID; public record DomainEvent(UUID eventId,String eventType,Instant occurredAt,UUID actorId,UUID warehouseId,UUID productId,String entityType,UUID entityId,String referenceType,UUID referenceId,String payload) { public static DomainEvent of(String type,UUID actor,UUID warehouse,UUID product,String entity,UUID id,String payload){return new DomainEvent(UUID.randomUUID(),type,Instant.now(),actor,warehouse,product,entity,id,null,null,payload);} }
